declare(strict_types=1);require __DIR__.'/bootstrap.php';require_once __DIR__.'/agent-runtime.php';$u=sf_require_user(false,true);$b=sf_request_json();$text=sf_clean_text($b['text']??'',1800);if($text==='')sf_json_response(['ok'=>false,'message'=>'No speech text supplied.'],422);$v=sf_ai_resolve_voice();if(!$v||$v['provider']!=='elevenlabs')sf_json_response(['ok'=>false,'error'=>'voice_unavailable','message'=>'ElevenLabs voice is not configured.'],503);$cost=max(1,(int)ceil(strlen($text)/4));$allow=sf_can_use_ai($u,$cost);if(!$allow['ok'])sf_json_response(['ok'=>false,'error'=>'active_tokens_required','message'=>'You are out of Active Tokens.'],402);$voice=trim((string)$v['voice_id']);if($voice==='')sf_json_response(['ok'=>false,'message'=>'Set an ElevenLabs Voice ID in Admin.'],503);$model=trim((string)$v['model'])?:'eleven_v3';try{$audio=sf_http_binary('https://api.elevenlabs.io/v1/text-to-speech/'.rawurlencode($voice).'?output_format=mp3_44100_128',['xi-api-key: '.$v['api_key']],['text'=>$text,'model_id'=>$model],50);$balance=sf_consume_ai($u,$cost,['provider'=>'elevenlabs','model'=>$model,'voice_chars'=>strlen($text)],'agent-voice');header('Content-Type: audio/mpeg');header('Cache-Control: no-store');header('X-Stonefellow-Active-Tokens: '.(($u['role']??'')==='admin'?'unlimited':(string)$balance));echo $audio;exit;}catch(Throwable $e){sf_json_response(['ok'=>false,'error'=>'voice_failed','message'=>'Voice generation failed: '.$e->getMessage()],503);}
